base.config.go:
package main

import "os"

const DBURLKey = "DB_URL"

func dbURL() string {
	if v := os.Getenv(DBURLKey); v != "" {
		return v
	}
	return "postgres://localhost/dev"
}

base.main.go:
package main

import "os"

func main() {
	url := os.Getenv("DB_URL")
	if url == "" {
		url = dbURL()
	}
	connect(url)
}

